# The floor starts on emergency lighting (the exit signs' glow) until the
# plant room's breaker is thrown.
# type          x     y     angle
# Entrance lobby: two storeys, glazed, entrance doors on the west, the
# reception desk facing them, stairs up to a railed balcony along the north
coop_start      1.5   3.5   0
# Doors (prototype): glass doors from the lobby into the offices (staff
# pass: blue, on the reception counter), and a
# double office doors between the corridor and the open plan: flush with the
# open plan, swinging out (south) into their recess off the corridor
door_sliding    8.5   4.5   0     lock=blue
door_double     12.5  10.5  90
# The plant room (for now, the small room south of the corridor): facilities
# pass (red), which is on the boss's desk
door_hinged     11.5  12.5  270   lock=red
